const practiceBody = `{"status":"solved","help_used":"hint","solved_on":"2026-11-09","time_spent":2100,"notes":"Keep this note"}`

// Generated by Codex and not thoroughly checked for correctness.
func TestPracticeHandlersPreserveAndClearFields(t *testing.T) {
	gin.SetMode(gin.TestMode)
	repository := newMockRepository()
	repository.expectedContext = t.Context()
	router := newListHandlerTestRouter(repository)
	addBody := `{"problem_id":"` + testProblemID + `","position":0,` + practiceBody[1:]
	added := performListRequest(t.Context(), router, http.MethodPut, itemCollectionPath(testListID), addBody)
	assertResponseStatus(t, added, http.StatusCreated)
	want := newListItemFixture()
	if err := json.Unmarshal([]byte(practiceBody), &want.Practice); err != nil {
		t.Fatal(err)
	}
	assertJSONBody(t, added, testutil.APIResponse{Message: testItemAddedMessage, Item: want})
	duplicate := performListRequest(t.Context(), router, http.MethodPut, itemCollectionPath(testListID), `{"problem_id":"`+testProblemID+`","position":99,"status":"not_started","notes":null}`)
	assertResponseStatus(t, duplicate, http.StatusConflict)
	assertJSONBody(t, duplicate, errorBody("Item already in list"))
	if !reflect.DeepEqual(repository.items[testListID][testProblemID], want) {
		t.Fatal("duplicate add changed the saved item")
	}

	path := itemPath(testListID, testProblemID)
	response := performListRequest(t.Context(), router, http.MethodPatch, path, `{"status":"in_progress"}`)
	assertResponseStatus(t, response, http.StatusOK)
	status := listitems.StatusInProgress
	want.Status = &status
	want.UpdatedAt = testItemCreatedAt().Add(time.Hour)
	assertJSONBody(t, response, testutil.APIResponse{Message: "Item updated", Item: want})
	response = performListRequest(t.Context(), router, http.MethodPatch, path, `{"notes":"","time_spent":0,"help_used":"none"}`)
	assertResponseStatus(t, response, http.StatusOK)
	seconds := int64(0)
	help := listitems.HelpNone
	want.Notes, want.TimeSpent, want.HelpUsed = nil, &seconds, &help
	assertJSONBody(t, response, testutil.APIResponse{Message: "Item updated", Item: want})
	response = performListRequest(t.Context(), router, http.MethodPatch, path, `{"status":null,"help_used":null,"solved_on":null,"time_spent":null,"notes":null}`)
	assertResponseStatus(t, response, http.StatusOK)
	want.Practice = listitems.Practice{}
	assertJSONBody(t, response, testutil.APIResponse{Message: "Item updated", Item: want})
	if repository.contextMismatch {
		t.Fatal("practice handlers did not pass request context")
	}
}

// Generated by Codex and not thoroughly checked for correctness.
func TestPracticeHandlersRejectInvalidRequestsWithoutMutation(t *testing.T) {
	for _, testCase := range []struct {
		name, body string
	}{
		{"invalid status", `{"status":"skipped"}`},
		{"invalid help", `{"help_used":"other"}`},
		{"invalid date", `{"solved_on":"2026-02-30"}`},
		{"negative time", `{"time_spent":-1}`},
		{"fractional time", `{"time_spent":0.5}`},
		{"overflow time", `{"time_spent":2147483648}`},
		{"overlong notes", fmt.Sprintf(`{"notes":%q}`, strings.Repeat("界", 513))},
	} {
		for _, method := range []string{http.MethodPut, http.MethodPatch} {
			t.Run(testCase.name+" "+method, func(t *testing.T) {
				gin.SetMode(gin.TestMode)
				repository := newMockRepository()
				original := newListItemFixture()
				repository.storeItem(original)
				path, body := itemPath(testListID, testProblemID), testCase.body
				if method == http.MethodPut {
					path = itemCollectionPath(testListID)
					body = `{"problem_id":"` + testProblemID + `","position":0,` + body[1:]
				}
				response := performListRequest(t.Context(), newListHandlerTestRouter(repository), method, path, body)
				assertResponseStatus(t, response, http.StatusBadRequest)
				if len(repository.calls) != 0 || !reflect.DeepEqual(repository.items[testListID][testProblemID], original) {
					t.Fatal("invalid practice request reached repository or changed item")
				}
			})
		}
	}
}

