func TestItemPatchErrors(t *testing.T) {
	for _, testCase := range []struct {
		name, listID, problemID, body, message string
		setup                                  func(*mockRepository)
		status                                 int
	}{
		{"empty patch", "7", testProblemID, `{}`, testInvalidFormatMessage, nil, 400},
		{"null patch", "7", testProblemID, `null`, testInvalidFormatMessage, nil, 400},
		{"unknown field", "7", testProblemID, `{"initialize_only":true}`, testInvalidFormatMessage, nil, 400},
		{"position cannot be patched", "7", testProblemID, `{"position":2}`, testInvalidFormatMessage, nil, 400},
		{"trailing body", "7", testProblemID, `{"notes":"x"} {}`, testInvalidFormatMessage, nil, 400},
		{"malformed trailing content", "7", testProblemID, `{"notes":"x"} garbage`, testInvalidFormatMessage, nil, 400},
		{"malformed JSON", "7", testProblemID, `{"notes":`, testInvalidFormatMessage, nil, 400},
		{"malformed list ID", "invalid", testProblemID, `{"notes":"x"}`, testInvalidListIDMessage, nil, 400},
		{"missing item", "7", "absent", `{"notes":"x"}`, "Item does not exist", nil, 404},
		{"foreign list", "7", testProblemID, `{"notes":"x"}`, "Item does not exist", clearLists, 404},
		{"repository error", "7", testProblemID, `{"notes":"x"}`, "Failed to update item", operationFailure(updateListItemOperation), 500},
		{"repository validation", "7", testProblemID, `{"notes":"x"}`, listitems.ErrInvalidPractice.Error(), func(repository *mockRepository) {
			repository.operationErrors[updateListItemOperation] = fmt.Errorf("private detail: %w", listitems.ErrInvalidPractice)
		}, 400},
	} {
		t.Run(testCase.name, func(t *testing.T) {
			gin.SetMode(gin.TestMode)
			repository := newMockRepository()
			repository.storeItem(newListItemFixture())
			repository.expectedContext = t.Context()
			if testCase.setup != nil {
				testCase.setup(repository)
			}
			response := performListRequest(t.Context(), newListHandlerTestRouter(repository), http.MethodPatch, itemPath(testCase.listID, testCase.problemID), testCase.body)
			assertResponseStatus(t, response, testCase.status)
			assertJSONBody(t, response, errorBody(testCase.message))
		})
	}
}
